package main

import "net/http"

const publicPageStyle = `<style>body{font:17px/1.6 system-ui,sans-serif;color:#17212f;background:#fff;max-width:760px;margin:0 auto;padding:32px 20px}h1,h2{line-height:1.25}h1{font-size:2rem}h2{font-size:1.3rem;margin-top:2rem}a{color:#165dc2}nav{margin:0 0 2rem}footer{border-top:1px solid #d9dfe7;margin-top:3rem;padding-top:1rem;color:#526070}</style>`

func servePublicPage(w http.ResponseWriter, body string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'")
	w.Header().Set("Cache-Control", "public, max-age=3600")
	_, _ = w.Write([]byte(body))
}

func serveAboutPage(w http.ResponseWriter, _ *http.Request) {
	servePublicPage(w, `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Line Host® Meet Planner</title>`+publicPageStyle+`<main><nav><a href="https://linehost.cloud/">Line Host®</a></nav><h1>Line Host® Meet Planner</h1><p>Crie ou agende reuniões Google Meet dentro do Mattermost, no navegador ou no aplicativo Desktop. Cada pessoa conecta sua própria Conta Google. O plugin publica o link na conversa escolhida e pode avisar no canal em vários momentos antes da reunião.</p><h2>Como funciona</h2><ol><li>O administrador instala o plugin e configura um cliente OAuth do Google.</li><li>Cada usuário conecta sua Conta Google e autoriza as permissões exibidas pelo Google.</li><li>Ao clicar em Meet na caixa de mensagem, o usuário inicia uma sala ou agenda um evento no Google Calendar com link do Meet.</li><li>Para reuniões agendadas, o usuário escolhe avisos no canal de 1 dia a 5 minutos antes.</li></ol><p>Os convidados recebem o convite pelo Google Calendar. O link e os avisos aparecem na conversa do Mattermost escolhida pelo organizador.</p><h2>Permissões Google</h2><p>O plugin solicita permissão para criar salas Google Meet e para criar eventos no Google Calendar. O plugin solicita acesso aos eventos dos calendários que o usuário possui e usa essa permissão para criar o evento solicitado na agenda principal.</p><p><a href="./privacy">Leia a política de privacidade do Meet Planner</a> · <a href="https://linehost.cloud/termos-de-uso/">Termos de uso da Line Host®</a></p></main><footer>Line Host® Meet Planner · Contato: <a href="mailto:suporte@linehost.cloud">suporte@linehost.cloud</a></footer></html>`)
}

func servePrivacyPage(w http.ResponseWriter, _ *http.Request) {
	servePublicPage(w, `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Privacidade do Line Host® Meet Planner</title>`+publicPageStyle+`<main><nav><a href="./about">Line Host® Meet Planner</a></nav><h1>Privacidade do Line Host® Meet Planner</h1><p>Esta política descreve o uso de dados Google pelo plugin Line Host® Meet Planner instalado em um servidor Mattermost. Última atualização: 4 de novembro de 2026.</p><h2>Dados acessados e finalidade</h2><p>Quando você conecta sua Conta Google, o plugin recebe tokens OAuth para agir com as permissões que você concedeu. A permissão de Google Meet é usada para criar salas de reunião. Ao agendar, o plugin envia ao Google Calendar o título, o horário, o fuso e os endereços de e-mail dos convidados que você informou para criar um evento com link do Meet. A função de agendamento não lista seus eventos existentes.</p><h2>Armazenamento e compartilhamento</h2><p>Os tokens OAuth são armazenados de forma criptografada no banco de dados do servidor Mattermost onde o plugin está instalado. O link do Meet, título e horário da reunião são publicados na conversa escolhida. Se você selecionou lembretes, o plugin guarda os dados necessários para enviá-los no canal e menciona o organizador. Convidados recebem convites pelo Google Calendar. O plugin faz chamadas diretamente do servidor Mattermost às APIs do Google; ele não envia tokens ou dados de reunião a um serviço da Line Host®.</p><h2>Retenção e controle</h2><p>Você pode desconectar sua Conta Google no plugin para remover os tokens armazenados por ele. Lembretes são removidos após o envio ou quando expiram. As mensagens publicadas seguem as políticas de retenção do administrador do Mattermost; os eventos criados seguem as configurações da sua Conta Google. Você pode revogar o acesso do aplicativo nas configurações de segurança da sua Conta Google.</p><h2>Uso limitado</h2><p>Os dados obtidos pelas APIs do Google são usados apenas para as funções descritas acima. O plugin não os utiliza para anúncios, venda de dados ou treinamento de modelos de inteligência artificial.</p><h2>Contato</h2><p>Para dúvidas ou solicitações sobre privacidade, escreva para <a href="mailto:suporte@linehost.cloud">suporte@linehost.cloud</a>.</p><p><a href="./about">Voltar à página do Meet Planner</a></p></main><footer>Line Host® Meet Planner</footer></html>`)
}
